export type EbookBlock =
  | {
      type: 'heading';
      text: string;
      number?: number;
      level?: 'major' | 'sub';
    }
  | {
      type: 'paragraph';
      text: string;
      emphasis?: boolean;
    }
  | {
      type: 'point';
      number: number;
      title: string;
      paragraphs: string[];
      bullets?: string[];
      afterBullets?: string[];
    }
  | {
      type: 'bullets';
      items: string[];
    }
  | {
      type: 'numberedList';
      items: string[];
    }
  | {
      type: 'table';
      headers: string[];
      rows: string[][];
    }
  | {
      type: 'callout';
      kind: 'principle' | 'tip';
      label: string;
      text: string;
    }
  | {
      type: 'divider';
    };

export interface EbookChapter {
  id: number;
  badge: string;
  title: string;
  subtitle?: string;
  isComingSoon?: boolean;
  blocks: EbookBlock[];
}

